// n8n Code Node - Location Parser
// Parses location input: coordinates, player name, or landmark

const input = $input.first().json.body.location; // e.g., "next to player Mauri67" or "-9, -60, 5"

function parseLocation(input) {
    if (!input || typeof input !== 'string') {
        return {
            type: 'invalid',
            error: 'Location must be a string'
        };
    }

    // PATTERN 0: JSON object with x, y, z
    // Matches: "{\"x\":375.26,\"y\":-60,\"z\":-505.5}" or '{"x":375.26,"y":-60,"z":-505.5}'
    try {
        const jsonObj = JSON.parse(input);
        if (jsonObj && typeof jsonObj === 'object' && 
            'x' in jsonObj && 'y' in jsonObj && 'z' in jsonObj) {
            return {
                type: 'coordinates',
                x: parseFloat(jsonObj.x),
                y: parseFloat(jsonObj.y),
                z: parseFloat(jsonObj.z),
                original: input
            };
        }
    } catch (e) {
        // Not valid JSON, continue to other patterns
    }

    // PATTERN 1: Explicit coordinates (x, y, z)
    // Matches: "100, -60, 200" or "100 -60 200" or "-100.5 -60.5 200.5"
    const coordMatch = input.match(
        /^\s*(-?\d+(?:\.\d+)?)\s*[,\s]\s*(-?\d+(?:\.\d+)?)\s*[,\s]\s*(-?\d+(?:\.\d+)?)\s*$/
    );
    if (coordMatch) {
        return {
            type: 'coordinates',
            x: parseFloat(coordMatch[1]),
            y: parseFloat(coordMatch[2]),
            z: parseFloat(coordMatch[3]),
            original: input
        };
    }

    // PATTERN 2: Player reference
    // Matches: "player Mauri67", "near player Mauri67", "next to player John", "by player X"
    const playerMatch = input.match(
        /(?:near|next\s+to|by)?\s*player\s+(\w+)/i
    );
    if (playerMatch) {
        return {
            type: 'player',
            name: playerMatch[1],
            original: input
        };
    }

    // PATTERN 3: Fallback - treat as landmark
    // "at spawn", "near village", etc.
    return {
        type: 'landmark',
        name: input.trim(),
        original: input
    };
}

const location = parseLocation(input);

// Optional: Log for debugging
console.log('Parsed location:', location);

return { location };

const position = $input.first().json.position || $input.first().json.location;
return {
  Position: {
    x: Math.floor(position?.x || 0),
    y: Math.floor(position?.y || -60),
    z: Math.floor(position?.z || 0)
  }
}

// Extract stages directly from Planner output
// No more coordinate replacement or dynamic division needed

const plan = $('Webhook').first().json.body.plan;

// Validate plan came back successfully
if (!plan || !plan.stages) {
  throw new Error('No valid plan received from Planner');
}

// Extract stages directly (already complete from planner)
const stages = plan.stages;
const totalStages = plan.metadata.totalStages;

console.log(`✅ Plan validated and ready`);
console.log(`Total stages: ${totalStages}`);
console.log(`Stages: ${Object.keys(stages).join(', ')}`);

// Optional: Minimal transformation if needed
// (e.g., convert stage format or add metadata)
const processedStages = {};
Object.entries(stages).forEach(([stageKey, stageData]) => {
  processedStages[stageKey] = {
    ...stageData,
    startTime: null,
    completedCount: 0
  };
});

return {
  stages: processedStages,
  totalStages: totalStages,
  metadata: plan.metadata,
  buildingRequest: plan.buildingRequest,
  coordinationStrategy: plan.coordinationStrategy,
  status: 'ready'
};

// Convert taskDivision placeholder coordinates (minX, midX, maxX, minZ, maxZ) to absolute

const buildLocation = $('Teleport Workers').first().json.buildLocation;
const taskDivision = $('Webhook').first().json.body.taskDivision;

const houseX = buildLocation.x;
const houseY = buildLocation.y;
const houseZ = buildLocation.z;

// 7x7 footprint centered at houseX, houseZ
const minX = Math.floor(houseX - 3);
const maxX = Math.floor(houseX + 3);
const midX = Math.floor(houseX);

const minZ = Math.floor(houseZ - 3);
const maxZ = Math.floor(houseZ + 3);

const floorY = houseY;
const wallHeight = 3;
const maxY = houseY + wallHeight;

console.log(`House footprint: x:${minX} to ${maxX}, z:${minZ} to ${maxZ}, y:${floorY} to ${maxY}`);
console.log(`Midline: x:${midX}`);

const updatedTasks = {};

Object.keys(taskDivision).forEach((workerName) => {
  const taskObj = taskDivision[workerName];

  // Determine this worker's x-range
  let workerXMin, workerXMax;
  if (workerName === "Worker1") {
    workerXMin = minX;
    workerXMax = midX;
  } else if (workerName === "Worker2") {
    workerXMin = midX;
    workerXMax = maxX;
  }

  console.log(`${workerName}: x:${workerXMin} to ${workerXMax}`);

  // ========== RECONSTRUCT TASK STRING WITH ABSOLUTE COORDINATES ==========
  let taskString = `${taskObj.objective}

Scope: ${taskObj.scope}
ABSOLUTE COORDINATES - x:${workerXMin} to ${workerXMax}, z:${minZ} to ${maxZ}, y:${floorY} to ${maxY}.
Your working region: x:${workerXMin} to ${workerXMax}.

Subtasks:
${taskObj.subtasks.map((s, i) => {
  // Replace placeholder coordinates in each subtask
  let updatedSubtask = s
    .replace(/x:\s*minX\s*to\s*midX/gi, `x:${workerXMin} to ${workerXMax}`)
    .replace(/x:\s*midX\s*to\s*maxX/gi, `x:${workerXMin} to ${workerXMax}`)
    .replace(/x:\s*minX\s*to\s*maxX/gi, `x:${minX} to ${maxX}`)
    .replace(/z:\s*minZ\s*to\s*maxZ/gi, `z:${minZ} to ${maxZ}`)
    .replace(/height.*\(e\.g\.,\s*\d+\s*blocks\s*tall\)/gi, `height (${wallHeight} blocks tall)`)
    .replace(/3\s*blocks?\s*tall/gi, `${wallHeight} blocks tall`)
    .replace(/midX/g, `x:${midX}`)
    .replace(/midline/g, `midline at x:${midX}`)
    .replace(/minX/g, `${minX}`)
    .replace(/maxX/g, `${maxX}`)
    .replace(/minZ/g, `${minZ}`)
    .replace(/maxZ/g, `${maxZ}`);

  return `${i + 1}. ${updatedSubtask}`;
}).join('\n')}

Block Break Limit: ${taskObj.blockBreakLimit}

Assumptions: ${taskObj.assumptions}

Constraints: ${taskObj.constraints}
- Do NOT build outside x:${workerXMin} to ${workerXMax}

CRITICAL: Use ABSOLUTE coordinates x:${workerXMin} to ${workerXMax}, z:${minZ} to ${maxZ}, y:${floorY} to ${maxY}.
House center: (${houseX}, ${houseY}, ${houseZ})
${workerName === "Worker1" ? `Your right boundary: x:${midX}` : `Your left boundary: x:${midX}`}

Work together with nearby workers to create a cohesive structure. Position yourself strategically to connect your work with others.`;

  updatedTasks[workerName] = taskString;
});

return updatedTasks;
